local TERMINAL = "com.superlogical.terminal"
-- The applied mood is remembered beside this file so hue-watch.lua can reuse it.
local dir = debug.getinfo(1, "S").source:gsub("^@", ""):match("^(.*)/") or "."
local STATE = dir .. "/hue-mood"

--- The last applied mood id, or nil when none is recorded.
function M.current()
  local file = io.open(STATE, "r")
  if not file then return nil end
  local id = (file:read("*a") or ""):match("^%s*(.-)%s*$")
  file:close()
  if M.themes[id] then return id end
  return nil
end

--- Theme every terminal in the current session with mood `id` and record it.
function M.apply(id)
  local theme = M.themes[id]
  if not theme then error("hue: unknown mood " .. tostring(id), 0) end
  local listing, list_err = rex.session.list_blocks({})
  if not listing then error(list_err, 0) end
  local themed = 0
  for _, block in ipairs(listing.blocks or {}) do
    if block.creator_name == TERMINAL then
      local _, err = rex.block.call(TERMINAL, "set_theme", {
        block_id = block.block_id,
        background = theme.background,
        foreground = theme.foreground,
        cursor = theme.cursor,
        palette = theme.palette,
        scheme = theme.scheme,
      })
      if err then error(err, 0) end
      themed = themed + 1
    end
  end
  local file, open_err = io.open(STATE, "w")
  if not file then error(open_err, 0) end
  local ok, write_err = file:write(id)
  file:close()
  if not ok then error(write_err, 0) end
  return { mood = id, themed = themed }
end

for _, id in ipairs(M.moods) do
  rex.action({
    name = "hue_" .. id,
    title = "Hue: " .. M.themes[id].label,
    category = "Hue",
    run = function()
      return M.apply(id)
    end,
  })
end

return M
